import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.CCCdsIgc.js";const m=JSON.parse('{"title":"可观测性（OpenTelemetry）","description":"","frontmatter":{},"headers":[],"relativePath":"admin/observability.md","filePath":"admin/observability.md"}'),l={name:"admin/observability.md"};function n(i,t,s,d,c,p){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="可观测性-opentelemetry" tabindex="-1">可观测性（OpenTelemetry） <a class="header-anchor" href="#可观测性-opentelemetry" aria-label="Permalink to &quot;可观测性（OpenTelemetry）&quot;">​</a></h1><p>公司如果已经有可观测平台（OpenTelemetry Collector、Grafana、Jaeger、SigNoz、云厂商的 APM 等），可以把 FlyknitBuddy 的调用数据也接进去：某个任务为什么慢、哪个模型最近错误多、哪个连接器的工具经常失败，都能和其他系统放在一起看。</p><h2 id="会发什么" tabindex="-1">会发什么 <a class="header-anchor" href="#会发什么" aria-label="Permalink to &quot;会发什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>内容</th></tr></thead><tbody><tr><td>每一次模型调用</td><td>模型、场景、输入 / 输出 token、耗时、是否出错</td></tr><tr><td>每一次工具调用</td><td>工具名、风险判定、谁批准的、成功与否、是主助手还是专家调的</td></tr></tbody></table><p>同一个任务的调用在同一条追踪（trace）里，点开就能看到这个任务先后调了几次模型、用了哪些工具、每一步多久。</p><p><strong>不会发</strong>：对话内容、工具的参数和结果、文件路径。默认也不带电脑名和使用者，只带电脑编号和部门。</p><h2 id="怎么打开" tabindex="-1">怎么打开 <a class="header-anchor" href="#怎么打开" aria-label="Permalink to &quot;怎么打开&quot;">​</a></h2><p>后台「<strong>运维 → 可观测性</strong>」（超级管理员才能修改）：</p><ol><li>填<strong>采集器地址</strong>，例如 OpenTelemetry Collector 的 OTLP/HTTP 端口；会自动加上 <code>/v1/traces</code>；</li><li>采集器要认证的，加一个<strong>请求头</strong>（比如 <code>Authorization</code>），值保存后加密，页面上不再显示；</li><li>点「<strong>发一条测试数据</strong>」，确认采集器收到了；</li><li>打开「<strong>导出</strong>」开关并保存。</li></ol><p>页面下方能看到已发出、排队中、丢弃的条数和最近一次出错的原因。采集器出问题时只会丢掉那一批数据，不会影响员工使用。</p><div class="tip custom-block"><p class="custom-block-title">带上电脑和使用者</p><p>需要按人排查时，可以打开「带上电脑和使用者」。这些数据会进入公司的可观测平台，请先确认符合公司的隐私规定。</p></div>',11)])])}const b=e(l,[["render",n]]);export{m as __pageData,b as default};
